#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum ErrorCode {
    /// 对象、来源、条件、版本或输入摘要不一致
    #[serde(rename = "bound_input_changed")]
    BoundInputChanged,
    /// 超过显式数据、时间、任务或迭代预算
    #[serde(rename = "budget_exceeded")]
    BudgetExceeded,
    /// 选定方法原档案或摄取缺失，不能核验旧task view来源freshness
    #[serde(rename = "current_task_method_source_freshness_unknown")]
    CurrentTaskMethodSourceUnknown,
    /// 方法原消息、档案、摄取、当前对象/basis/fact/source登记冲突
    #[serde(rename = "current_task_method_source_refuted")]
    CurrentTaskMethodSourceRefuted,
    /// 原/2完整task和方法来源观察与本次重算不相同
    #[serde(rename = "current_task_method_view_stale")]
    CurrentTaskMethodViewStale,
    /// 规范缺失、歧义、身份或映射不成立
    #[serde(rename = "design_invalid")]
    DesignInvalid,
    /// 实际 ggen 未完成全部必需产物
    #[serde(rename = "generation_failed")]
    GenerationFailed,
    /// 生成工具或输入不符合锁定身份
    #[serde(rename = "generation_identity_mismatch")]
    GenerationIdentityMismatch,
    /// 权限、基线、前驱或状态条件未满足
    #[serde(rename = "governance_denied")]
    GovernanceDenied,
    /// 输入或结果违反接口合同
    #[serde(rename = "invalid_contract")]
    InvalidContract,
    /// 实际原生工具不可用或未建立能力
    #[serde(rename = "native_unavailable")]
    NativeUnavailable,
    /// 正式执行范围外的查询或约束
    #[serde(rename = "query_unsupported")]
    QueryUnsupported,
    /// 信息、目标或覆盖不足
    #[serde(rename = "semantic_unknown")]
    SemanticUnknown,
}
impl ErrorCode {
    pub fn code(self) -> &'static str {match self {
        Self::BoundInputChanged => "bound_input_changed",
        Self::BudgetExceeded => "budget_exceeded",
        Self::CurrentTaskMethodSourceUnknown => "current_task_method_source_freshness_unknown",
        Self::CurrentTaskMethodSourceRefuted => "current_task_method_source_refuted",
        Self::CurrentTaskMethodViewStale => "current_task_method_view_stale",
        Self::DesignInvalid => "design_invalid",
        Self::GenerationFailed => "generation_failed",
        Self::GenerationIdentityMismatch => "generation_identity_mismatch",
        Self::GovernanceDenied => "governance_denied",
        Self::InvalidContract => "invalid_contract",
        Self::NativeUnavailable => "native_unavailable",
        Self::QueryUnsupported => "query_unsupported",
        Self::SemanticUnknown => "semantic_unknown",
    }}
}

