#[serde(deny_unknown_fields)]
pub struct BaseStructuredResult {
    /// 逻辑请求和每次尝试分别追溯；失败不变为已采用知识；字段 attempts
    pub attempts: Vec<BaseStructuredAttempt>,
    /// 逻辑请求和每次尝试分别追溯；失败不变为已采用知识；字段 execution
    pub execution: String,
    /// 逻辑请求和每次尝试分别追溯；失败不变为已采用知识；字段 failure
    pub failure: Option<SemanticProviderFailure>,
    /// 逻辑请求和每次尝试分别追溯；失败不变为已采用知识；字段 logical_request_sha256
    pub logical_request_sha256: String,
    /// 逻辑请求和每次尝试分别追溯；失败不变为已采用知识；字段 output
    #[serde(deserialize_with = "semantica_contracts::json::deserialize_preserved")]
    pub output: serde_json::Value,
    /// 逻辑请求和每次尝试分别追溯；失败不变为已采用知识；字段 schema
    pub schema: String,
}
