/// 当前Rust书籍来源检查的独立执行身份；与旧native RECORD/SourceLock分离
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BookSourceExecution {
    /// 工程适配独立批准的历史书籍数据版摘要
    pub approved_archive_sha256: String,
    /// 作者来源路径选择，相对skill或点表示当前根
    pub book_root: String,
    /// 实际Rust引擎
    pub engine: String,
    /// 未执行或验证错误；正常已执行blocked不制造执行错误
    pub error: Option<String>,
    /// 本次实际Rust执行文件完整SHA
    pub executable_sha256: String,
    /// 本次Rust执行文件实际字节数
    pub executable_size_bytes: u64,
    /// 复用同一编译来源清单，绑定拥有的Rust/TOML、本地解析器/求值器、规格模板与实际两组合同；外部缓存和原生依赖仍未覆盖
    pub implementation_sources: Vec<BookSourceInputBinding>,
    /// 所有已读或尝试但缺失的来源，包括归档/continuity
    pub input_bindings: Vec<BookSourceInputBinding>,
    /// 完整原检查结果canonical JSON字节身份
    pub result_sha256: String,
    /// 独立Rust执行协议
    pub schema: String,
    /// 来源检查已执行或批准源不可用未执行；blocked另存
    pub semantic_execution: String,
    /// 实际数据归档字节身份或不可用
    pub source_archive_sha256: Option<String>,
}
impl BookSourceExecution {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.approved_archive_sha256.len() != 64 || !self.approved_archive_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("BookSourceExecution.approved_archive_sha256:sha256".into()); }
        if self.book_root.trim().is_empty() { failures.push("BookSourceExecution.book_root:required".into()); }
        if self.engine.trim().is_empty() { failures.push("BookSourceExecution.engine:required".into()); }
        if self.executable_sha256.len() != 64 || !self.executable_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("BookSourceExecution.executable_sha256:sha256".into()); }
        if self.result_sha256.len() != 64 || !self.result_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("BookSourceExecution.result_sha256:sha256".into()); }
        if self.schema.trim().is_empty() { failures.push("BookSourceExecution.schema:required".into()); }
        if self.semantic_execution.trim().is_empty() { failures.push("BookSourceExecution.semantic_execution:required".into()); }

        if !["semantica.rust-runtime",].contains(&self.engine.as_str()) { failures.push("BookSourceExecution.engine:status".into()); }
        if !["ontology-engineering.book-source-rust-execution/v1",].contains(&self.schema.as_str()) { failures.push("BookSourceExecution.schema:status".into()); }
        if !["completed","not_run",].contains(&self.semantic_execution.as_str()) { failures.push("BookSourceExecution.semantic_execution:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

