/// 完整代码资格结果独立于比较执行/工程采用；缺适配器明确not_connected
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CodeArtifactEligibilityResult {
    /// 描述符原字节SHA，不冒认binary摘要
    pub artifact_sha256: String,
    /// 比较来源原字节SHA，不表示可信批准
    pub comparison_sha256: String,
    /// 独立资格结论
    pub eligibility: String,
    /// 资格检查执行状态
    pub execution: String,
    /// 资格未建立的实际原因
    pub reason: String,
    /// oev2.code-artifact-eligibility-result/1
    pub schema: String,
    /// 外部/原生/资格适配器与真正use-feedback-recover未覆盖
    pub uncovered: Vec<String>,
}
impl CodeArtifactEligibilityResult {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.artifact_sha256.len() != 64 || !self.artifact_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("CodeArtifactEligibilityResult.artifact_sha256:sha256".into()); }
        if self.comparison_sha256.len() != 64 || !self.comparison_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("CodeArtifactEligibilityResult.comparison_sha256:sha256".into()); }
        if self.eligibility.trim().is_empty() { failures.push("CodeArtifactEligibilityResult.eligibility:required".into()); }
        if self.execution.trim().is_empty() { failures.push("CodeArtifactEligibilityResult.execution:required".into()); }
        if self.reason.trim().is_empty() { failures.push("CodeArtifactEligibilityResult.reason:required".into()); }
        if self.schema.trim().is_empty() { failures.push("CodeArtifactEligibilityResult.schema:required".into()); }

        if !["denied","eligible","not_connected","unknown",].contains(&self.eligibility.as_str()) { failures.push("CodeArtifactEligibilityResult.eligibility:status".into()); }
        if !["completed","failed","not_run",].contains(&self.execution.as_str()) { failures.push("CodeArtifactEligibilityResult.execution:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

