/// Typed observation of successful reason result or an exact observed semantic refusal, independent of actual process completion
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CodeSemanticReplayOutcome {
    /// Exact independently fixed rejection condition, not a generic failure bucket; absent on success
    pub condition: Option<String>,
    /// Actual classified port failure or typed decode failure; original nonempty diagnostic retained
    pub failure: Option<SemanticRuntimeFailure>,
    /// Actual semantic success or classified refusal reached within a completed runner; never infrastructure failure
    pub outcome: String,
    /// True only after the generated reason port was actually invoked; boolean iteration decode refusal remains false
    pub reason_port_invoked: bool,
    /// Canonical identity of complete request including metadata and iteration type before decoding
    pub request_sha256: String,
    /// Complete port result on success only; absence on refusal means no partial closure is promoted
    pub result: Option<SemanticReasonResult>,
    /// Explicit nested outcome protocol; an outer crash or timeout cannot serialize this as success
    pub schema: String,
    /// Actual top-level request decoding or invocation of the generated SemanticReasonPort
    pub stage: String,
}
impl CodeSemanticReplayOutcome {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if let Some(value) = &self.failure { if let Err(errors) = value.validate() { failures.extend(errors); } }

        if self.outcome.trim().is_empty() { failures.push("CodeSemanticReplayOutcome.outcome:required".into()); }
        if self.request_sha256.len() != 64 || !self.request_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("CodeSemanticReplayOutcome.request_sha256:sha256".into()); }
        if let Some(value) = &self.result { if let Err(errors) = value.validate() { failures.extend(errors); } }

        if self.schema.trim().is_empty() { failures.push("CodeSemanticReplayOutcome.schema:required".into()); }
        if self.stage.trim().is_empty() { failures.push("CodeSemanticReplayOutcome.stage:required".into()); }

        if !["rejected","success",].contains(&self.outcome.as_str()) { failures.push("CodeSemanticReplayOutcome.outcome:status".into()); }
        if !["oev2.code-semantic-replay-outcome/1",].contains(&self.schema.as_str()) { failures.push("CodeSemanticReplayOutcome.schema:status".into()); }
        if !["reason","request_decode",].contains(&self.stage.as_str()) { failures.push("CodeSemanticReplayOutcome.stage:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

