/// 工程本体先规定经验分类及接纳条件，当前Rust凝练回执引用唯一入口；ggen生成合同，不以模型答复或旧入口通过替代当前验证
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ConsolidationHandoff {
    /// 同一Project的当前工程检查入口
    pub current_review_entrypoint: String,
    /// 当前根的总入口说明
    pub entrypoint: String,
    /// 当前入口仅供agent接续，本次未调用
    pub entrypoint_usage: String,
    /// 同一当前根的Rust本体候选入口；这里只引用，不执行
    pub native_proposal_entrypoint: String,
    /// 本份聊天凝练尚未取得当前registry执行/验证
    pub native_proposal_migration: String,
    /// 依据本轮judgments的完整程度及经验分类继续补证据、审查本体候选、整理操作经验或保留no_delta
    pub next_action: String,
    /// 任何非空PackageDelta接续仍须满足的来源、条件、反例、真实Rust执行与治理要求
    pub required: Vec<String>,
    /// 当前凝练交接协议
    pub schema: String,
}
impl ConsolidationHandoff {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.current_review_entrypoint.trim().is_empty() { failures.push("ConsolidationHandoff.current_review_entrypoint:required".into()); }
        if self.entrypoint.trim().is_empty() { failures.push("ConsolidationHandoff.entrypoint:required".into()); }
        if self.entrypoint_usage.trim().is_empty() { failures.push("ConsolidationHandoff.entrypoint_usage:required".into()); }
        if self.native_proposal_entrypoint.trim().is_empty() { failures.push("ConsolidationHandoff.native_proposal_entrypoint:required".into()); }
        if self.native_proposal_migration.trim().is_empty() { failures.push("ConsolidationHandoff.native_proposal_migration:required".into()); }
        if self.next_action.trim().is_empty() { failures.push("ConsolidationHandoff.next_action:required".into()); }
        if self.schema.trim().is_empty() { failures.push("ConsolidationHandoff.schema:required".into()); }

        if !["oev2 kernel review",].contains(&self.current_review_entrypoint.as_str()) { failures.push("ConsolidationHandoff.current_review_entrypoint:status".into()); }
        if !["SKILL.md",].contains(&self.entrypoint.as_str()) { failures.push("ConsolidationHandoff.entrypoint:status".into()); }
        if !["current_reference_only_not_invoked",].contains(&self.entrypoint_usage.as_str()) { failures.push("ConsolidationHandoff.entrypoint_usage:status".into()); }
        if !["oev2 semantics propose",].contains(&self.native_proposal_entrypoint.as_str()) { failures.push("ConsolidationHandoff.native_proposal_entrypoint:status".into()); }
        if !["current_registry_not_verified",].contains(&self.native_proposal_migration.as_str()) { failures.push("ConsolidationHandoff.native_proposal_migration:status".into()); }
        if !["complete_missing_judgments","retain_no_delta","review_candidates_and_construct_delta","review_judgments_and_choose_asset_kind",].contains(&self.next_action.as_str()) { failures.push("ConsolidationHandoff.next_action:status".into()); }
        if !["oev2.consolidation-handoff/1",].contains(&self.schema.as_str()) { failures.push("ConsolidationHandoff.schema:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

