/// 决定更新回执
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DecisionUpdateReceipt {
    /// 下游需重审的决定
    pub affected_decisions: Vec<String>,
    /// 新依据证据ID
    pub basis: Vec<String>,
    /// 新结论
    pub conclusion: String,
    /// 决定
    pub decision_id: String,
    /// 拒绝原因
    pub failures: Vec<String>,
    /// 原结论
    pub previous_conclusion: String,
    /// 原 Project 摘要
    pub previous_project_sha256: String,
    /// 新 Project 路径
    pub project_output: String,
    /// 新修订
    pub project_revision: String,
    /// 新 Project 摘要
    pub project_sha256: String,
    /// 回执版本
    pub schema: String,
    /// 证明范围
    pub scope: String,
    /// updated/refused
    pub status: String,
}
impl DecisionUpdateReceipt {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.conclusion.trim().is_empty() { failures.push("DecisionUpdateReceipt.conclusion:required".into()); }
        if self.decision_id.trim().is_empty() { failures.push("DecisionUpdateReceipt.decision_id:required".into()); }
        if self.previous_conclusion.trim().is_empty() { failures.push("DecisionUpdateReceipt.previous_conclusion:required".into()); }
        if self.previous_project_sha256.len() != 64 || !self.previous_project_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("DecisionUpdateReceipt.previous_project_sha256:sha256".into()); }
        if self.project_output.trim().is_empty() { failures.push("DecisionUpdateReceipt.project_output:required".into()); }
        if self.project_revision.trim().is_empty() { failures.push("DecisionUpdateReceipt.project_revision:required".into()); }
        if self.project_sha256.len() != 64 || !self.project_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("DecisionUpdateReceipt.project_sha256:sha256".into()); }
        if self.schema.trim().is_empty() { failures.push("DecisionUpdateReceipt.schema:required".into()); }
        if self.scope.trim().is_empty() { failures.push("DecisionUpdateReceipt.scope:required".into()); }
        if self.status.trim().is_empty() { failures.push("DecisionUpdateReceipt.status:required".into()); }

        if !["oev2.decision-update-receipt/1",].contains(&self.schema.as_str()) { failures.push("DecisionUpdateReceipt.schema:status".into()); }
        if !["refused","updated",].contains(&self.status.as_str()) { failures.push("DecisionUpdateReceipt.status:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

