    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.acceptance.trim().is_empty() { failures.push("DesignComparisonRule.acceptance:required".into()); }
        if self.owner.trim().is_empty() { failures.push("DesignComparisonRule.owner:required".into()); }
        if self.rule_id.trim().is_empty() { failures.push("DesignComparisonRule.rule_id:required".into()); }

        if let Some(value) = &self.direction { if !["higher","lower",].contains(&value.as_str()) { failures.push("DesignComparisonRule.direction:allowed_values".into()); } }
        if !["calculated_model","not_implemented",].contains(&self.owner.as_str()) { failures.push("DesignComparisonRule.owner:allowed_values".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
