/// 有界同步旋拧/退头与下一承托合同，服务当前对象和工程目的
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DriveContract {
    /// 累计角度合同比较容差，单位deg
    pub angular_tolerance: Quantity,
    /// 方向、零位和行程采用的同一空间坐标
    pub coordinate_frame: String,
    /// 有符号导程，单位mm/rev；正负由冻结轴向和手性约定
    pub lead: Quantity,
    /// 真实导程是否确认；假设仅支持条件几何
    pub lead_status: String,
    /// 几何合同比较容差，单位mm；不是制造或最终贴后验收
    pub linear_tolerance: Quantity,
    /// 本次有界动作的最大允许行程，单位mm
    pub maximum_travel: Quantity,
    /// 当前机构对象与来源版本
    pub object: ObjectIdentity,
    /// 按动作序列同一状态的全部参与者；不任意对号不同时间的轨迹
    pub samples: Vec<DriveSample>,
    /// 机制检查协议
    pub schema: String,
    /// 原运动合同、用户纠正、专利或原生几何来源
    pub source_refs: Vec<String>,
    /// 刀槽间隙接管角，单位deg；不是传矩容量证明
    pub takeup_angle: Quantity,
    /// 全机时间基准身份或明确未绑定
    pub time_basis: String,
    /// 时间是否已经绑定，不从局部样本号推定
    pub time_status: String,
    /// CAD、动画和检查应共同引用的轨迹身份
    pub trajectory_id: String,
}
impl DriveContract {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.coordinate_frame.trim().is_empty() { failures.push("DriveContract.coordinate_frame:required".into()); }
        if self.lead_status.trim().is_empty() { failures.push("DriveContract.lead_status:required".into()); }
        if let Err(errors) = self.object.validate() { failures.extend(errors); }

        if self.schema.trim().is_empty() { failures.push("DriveContract.schema:required".into()); }
        if self.time_basis.trim().is_empty() { failures.push("DriveContract.time_basis:required".into()); }
        if self.time_status.trim().is_empty() { failures.push("DriveContract.time_status:required".into()); }
        if self.trajectory_id.trim().is_empty() { failures.push("DriveContract.trajectory_id:required".into()); }

        if !["assumed","confirmed","unknown",].contains(&self.lead_status.as_str()) { failures.push("DriveContract.lead_status:status".into()); }
        if !["oev2.coupled-drive/1",].contains(&self.schema.as_str()) { failures.push("DriveContract.schema:status".into()); }
        if !["bound","unknown",].contains(&self.time_status.as_str()) { failures.push("DriveContract.time_status:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

/// 同步驱动和承力交接的同一离散样本；样本号不是动画帧号
