        if self.next_support.trim().is_empty() { failures.push("DriveSample.next_support:required".into()); }
        if self.phase.trim().is_empty() { failures.push("DriveSample.phase:required".into()); }
        if self.sample_id.trim().is_empty() { failures.push("DriveSample.sample_id:required".into()); }
        if self.screw_holder.trim().is_empty() { failures.push("DriveSample.screw_holder:required".into()); }

        if !["absent","present","unknown",].contains(&self.next_support.as_str()) { failures.push("DriveSample.next_support:status".into()); }
