#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ExperienceCandidate {
    /// 有范围的适用条件，不写无条件行业结论
    pub applicability: Vec<String>,
    /// 冻结候选的稳定身份；评估引用同一身份
    pub candidate_id: String,
    /// 不适用或已否定的情况
    pub counterexamples: Vec<String>,
    /// 已有本体表达、实例或缺口的精确归属
    pub existing_expression: String,
    /// 所需功能及本候选承担的操作作用
    pub function: String,
    /// 最多三个可检验假设；旧否定重试需新依据
    pub hypotheses: Vec<String>,
    /// 区分操作方法、本体知识和实现修复
    pub kind: String,
    /// 说明工程机制；未证实的物理机制写明 unknown
    pub mechanism: String,
    /// 工程对象及其修订、来源摘要和适用条件范围
    pub object: ObjectIdentity,
    /// 已有表达充分时保持 no_delta
    pub ontology_delta: String,
    /// 既有 Project 的稳定身份
    pub project_id: String,
    /// 原目的及必要功能的自然语言绑定
    pub purpose: String,
    /// 原始过程、旧资产与提取身份的引用
    pub sources: Vec<SourceCitation>,
    /// 工程与迁移未闭合项
    pub unknowns: Vec<String>,
    /// 后续独立验证和必要工程验收
    pub verification_requirements: Vec<String>,
}
impl ExperienceCandidate {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.candidate_id.trim().is_empty() { failures.push("ExperienceCandidate.candidate_id:required".into()); }
        if self.existing_expression.trim().is_empty() { failures.push("ExperienceCandidate.existing_expression:required".into()); }
        if self.function.trim().is_empty() { failures.push("ExperienceCandidate.function:required".into()); }
        if self.kind.trim().is_empty() { failures.push("ExperienceCandidate.kind:required".into()); }
        if self.mechanism.trim().is_empty() { failures.push("ExperienceCandidate.mechanism:required".into()); }
        if let Err(errors) = self.object.validate() { failures.extend(errors); }

        if self.ontology_delta.trim().is_empty() { failures.push("ExperienceCandidate.ontology_delta:required".into()); }
        if self.project_id.trim().is_empty() { failures.push("ExperienceCandidate.project_id:required".into()); }
        if self.purpose.trim().is_empty() { failures.push("ExperienceCandidate.purpose:required".into()); }

        if !["implementation_fix","ontology_knowledge","operation_method",].contains(&self.kind.as_str()) { failures.push("ExperienceCandidate.kind:status".into()); }
        if !["candidate","no_delta",].contains(&self.ontology_delta.as_str()) { failures.push("ExperienceCandidate.ontology_delta:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

