/// 同Project探索的不可覆盖步骤回执；保留前态、工具结果和当前待办，不建立第二项目账本
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct HostExplorationState {
    /// 仍为false，工程采用由原审查负责
    pub adopted: bool,
    /// 保持原冻结任务与判据
    pub frozen: ArtifactReference,
    /// 开发回放不证明方法收益
    pub method_benefit: String,
    /// 从冻结动作和实际前置结果派生的下一步，包含目的、完整验收、条件、工具输入与结果分支
    #[serde(deserialize_with = "semantica_contracts::json::deserialize_preserved")]
    pub pending: Vec<serde_json::Value>,
    /// 前态原件；失败历史不替换
    pub previous: Option<ArtifactReference>,
    /// 累积回读；按前态逐项重建，不能跳步或改旧结果
    pub receipts: Vec<HostExplorationReceipt>,
    /// 本次原请求，历史接续时重新读回
    pub request: ArtifactReference,
    /// 既有owner产生的结果、Project副本、work、任务视图与Harness引用；结果显式/2
    pub run: EngineeringExplorationRunResult,
    /// 显式宿主接续状态版本
    pub schema: String,
    /// 待宿主、已有结果或需重审；不表示工程达成
    pub status: String,
}
impl HostExplorationState {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.method_benefit.trim().is_empty() { failures.push("HostExplorationState.method_benefit:required".into()); }
        if self.schema.trim().is_empty() { failures.push("HostExplorationState.schema:required".into()); }
        if self.status.trim().is_empty() { failures.push("HostExplorationState.status:required".into()); }

        if !["unknown",].contains(&self.method_benefit.as_str()) { failures.push("HostExplorationState.method_benefit:allowed_values".into()); }
        if !["oev2.exploration-host-state/1",].contains(&self.schema.as_str()) { failures.push("HostExplorationState.schema:allowed_values".into()); }
        if !["needs_review","requires_host_agent","results_recorded",].contains(&self.status.as_str()) { failures.push("HostExplorationState.status:allowed_values".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

