/// 记忆召回候选的核验与登记报告；不支持决定
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MemoryCandidateCheck {
    /// 交接文件
    pub candidate: ArtifactReference,
    /// 登记用证据ID
    pub evidence_id: Option<String>,
    /// 拒绝原因
    pub failures: Vec<String>,
    /// memory 适用审查（原样）
    pub memory_scope: Option<String>,
    /// memory 列出的缺失条件
    pub missing_conditions: Vec<String>,
    /// Project 绑定
    pub project_binding: String,
    /// Project 修订
    pub project_revision: String,
    /// Project 摘要
    pub project_sha256: String,
    /// 经验id@r修订
    pub record: Option<String>,
    /// 重算的经验摘要
    pub record_sha256: Option<String>,
    /// 报告版本
    pub schema: String,
    /// 证明范围
    pub scope: String,
    /// 重读一致的原消息数
    pub sources_verified: u64,
    /// accepted/rejected/registered/refused
    pub status: String,
    /// 提示
    pub warnings: Vec<String>,
}
impl MemoryCandidateCheck {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.project_binding.trim().is_empty() { failures.push("MemoryCandidateCheck.project_binding:required".into()); }
        if self.project_revision.trim().is_empty() { failures.push("MemoryCandidateCheck.project_revision:required".into()); }
        if self.project_sha256.len() != 64 || !self.project_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("MemoryCandidateCheck.project_sha256:sha256".into()); }
        if let Some(value) = &self.record_sha256 { if value.len() != 64 || !value.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("MemoryCandidateCheck.record_sha256:sha256".into()); } }
        if self.schema.trim().is_empty() { failures.push("MemoryCandidateCheck.schema:required".into()); }
        if self.scope.trim().is_empty() { failures.push("MemoryCandidateCheck.scope:required".into()); }
        if self.status.trim().is_empty() { failures.push("MemoryCandidateCheck.status:required".into()); }

        if !["condition_changed","matched","object_changed","project_mismatch","unbound","unchecked",].contains(&self.project_binding.as_str()) { failures.push("MemoryCandidateCheck.project_binding:status".into()); }
        if !["oev2.memory-candidate-check/1",].contains(&self.schema.as_str()) { failures.push("MemoryCandidateCheck.schema:status".into()); }
        if !["accepted","refused","registered","rejected",].contains(&self.status.as_str()) { failures.push("MemoryCandidateCheck.status:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

