        if self.datum.trim().is_empty() { failures.push("NumericAcceptance.datum:required".into()); }
        if self.definition_status.trim().is_empty() { failures.push("NumericAcceptance.definition_status:required".into()); }
        if self.evidence_role.trim().is_empty() { failures.push("NumericAcceptance.evidence_role:required".into()); }
