/// 当前 Project 与历史模型的显式内容绑定；不能替代物理验证
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ProjectReviewContext {
    /// 工程采用条件的精确范围
    pub condition_scope: String,
    /// 该范围条件字符串的原始 UTF-8 内容 SHA-256；不推断物理真实性
    pub condition_sha256: String,
    /// 稳定工程对象身份
    pub object_id: String,
    /// 当前对象修订
    pub object_revision: String,
    /// 既有 Project 的稳定身份
    pub project_id: String,
    /// 当前项目修订；不由同名对象替代
    pub project_revision: String,
    /// Project 审查输入的规范 JSON SHA-256：身份、目的、对象、条件、输入来源及依赖；输出决定不形成循环摘要
    pub project_sha256: String,
    /// 版本化内部合同的协议身份
    pub schema: String,
    /// 当前来源字节 SHA-256
    pub source_sha256: String,
}
impl ProjectReviewContext {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.condition_scope.trim().is_empty() { failures.push("ProjectReviewContext.condition_scope:required".into()); }
        if self.condition_sha256.len() != 64 || !self.condition_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("ProjectReviewContext.condition_sha256:sha256".into()); }
        if self.object_id.trim().is_empty() { failures.push("ProjectReviewContext.object_id:required".into()); }
        if self.object_revision.trim().is_empty() { failures.push("ProjectReviewContext.object_revision:required".into()); }
        if self.project_id.trim().is_empty() { failures.push("ProjectReviewContext.project_id:required".into()); }
        if self.project_revision.trim().is_empty() { failures.push("ProjectReviewContext.project_revision:required".into()); }
        if self.project_sha256.len() != 64 || !self.project_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("ProjectReviewContext.project_sha256:sha256".into()); }
        if self.schema.trim().is_empty() { failures.push("ProjectReviewContext.schema:required".into()); }
        if self.source_sha256.len() != 64 || !self.source_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("ProjectReviewContext.source_sha256:sha256".into()); }

        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

