/// 先基线、后候选的量测比较请求
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ToolComparisonRequest {
    /// 基线结果文件
    pub baseline: ArtifactReference,
    /// 候选结果文件
    pub candidate: ArtifactReference,
    /// 比较标识
    pub comparison_id: String,
    /// lower_is_better/higher_is_better
    pub direction: String,
    /// 比较指标
    pub metric: String,
    /// 判定改善的最小相对改善（0~1）
    pub minimum_improvement: f64,
    /// 每侧最少样本数
    pub minimum_samples: u64,
    /// 合同版本
    pub schema: String,
    /// 单位
    pub unit: String,
}
impl ToolComparisonRequest {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.comparison_id.trim().is_empty() { failures.push("ToolComparisonRequest.comparison_id:required".into()); }
        if self.direction.trim().is_empty() { failures.push("ToolComparisonRequest.direction:required".into()); }
        if self.metric.trim().is_empty() { failures.push("ToolComparisonRequest.metric:required".into()); }
        if !self.minimum_improvement.is_finite() { failures.push("ToolComparisonRequest.minimum_improvement:finite".into()); }
        if self.schema.trim().is_empty() { failures.push("ToolComparisonRequest.schema:required".into()); }
        if self.unit.trim().is_empty() { failures.push("ToolComparisonRequest.unit:required".into()); }

        if !["higher_is_better","lower_is_better",].contains(&self.direction.as_str()) { failures.push("ToolComparisonRequest.direction:status".into()); }
        if !["oev2.tool-comparison/1",].contains(&self.schema.as_str()) { failures.push("ToolComparisonRequest.schema:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

