/// 工具结果核验报告
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ToolResultCheck {
    /// observed_findings/none
    pub decision_support: String,
    /// 拒绝原因代码
    pub failures: Vec<String>,
    /// 外部导入结论数
    pub findings_imported: u64,
    /// 推断结论数
    pub findings_inferred: u64,
    /// 观察结论数
    pub findings_observed: u64,
    /// 未知结论数
    pub findings_unknown: u64,
    /// matched/object_changed/condition_changed/source_changed/project_mismatch
    pub project_binding: String,
    /// 调用后 Project 是否另有修订
    pub project_revised_since_run: bool,
    /// 核验通过的原始记录数
    pub records_verified: u64,
    /// 结果标识
    pub result_id: String,
    /// 结果文件字节摘要
    pub result_sha256: String,
    /// 报告版本
    pub schema: String,
    /// 证明范围
    pub scope: String,
    /// accepted/rejected
    pub status: String,
    /// manifest_matched/manifest_changed/manifest_unavailable/not_declared
    pub subject_status: String,
    /// qualified/registered_unqualified/retired/unregistered/version_mismatch/executable_changed/executable_unavailable
    pub tool_status: String,
    /// 提示
    pub warnings: Vec<String>,
}
impl ToolResultCheck {
    pub fn validate(&self) -> Result<(), Vec<String>> {
        #[allow(unused_mut)]
        let mut failures = Vec::new();
        if self.decision_support.trim().is_empty() { failures.push("ToolResultCheck.decision_support:required".into()); }
        if self.project_binding.trim().is_empty() { failures.push("ToolResultCheck.project_binding:required".into()); }
        if self.result_id.trim().is_empty() { failures.push("ToolResultCheck.result_id:required".into()); }
        if self.result_sha256.len() != 64 || !self.result_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("ToolResultCheck.result_sha256:sha256".into()); }
        if self.schema.trim().is_empty() { failures.push("ToolResultCheck.schema:required".into()); }
        if self.scope.trim().is_empty() { failures.push("ToolResultCheck.scope:required".into()); }
        if self.status.trim().is_empty() { failures.push("ToolResultCheck.status:required".into()); }
        if self.subject_status.trim().is_empty() { failures.push("ToolResultCheck.subject_status:required".into()); }
        if self.tool_status.trim().is_empty() { failures.push("ToolResultCheck.tool_status:required".into()); }

        if !["none","observed_findings",].contains(&self.decision_support.as_str()) { failures.push("ToolResultCheck.decision_support:status".into()); }
        if !["condition_changed","matched","object_changed","project_mismatch","source_changed",].contains(&self.project_binding.as_str()) { failures.push("ToolResultCheck.project_binding:status".into()); }
        if !["oev2.tool-result-check/1",].contains(&self.schema.as_str()) { failures.push("ToolResultCheck.schema:status".into()); }
        if !["accepted","rejected",].contains(&self.status.as_str()) { failures.push("ToolResultCheck.status:status".into()); }
        if !["manifest_changed","manifest_matched","manifest_unavailable","not_declared",].contains(&self.subject_status.as_str()) { failures.push("ToolResultCheck.subject_status:status".into()); }
        if !["executable_changed","executable_unavailable","qualified","registered_unqualified","retired","unregistered","version_mismatch",].contains(&self.tool_status.as_str()) { failures.push("ToolResultCheck.tool_status:status".into()); }
        if failures.is_empty() { Ok(()) } else { Err(failures) }
    }
}

