        if self.report_sha256.len() != 64 || !self.report_sha256.bytes().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) { failures.push("TypedPromotedProjectReviewReceipt1.report_sha256:sha256".into()); }
